const test = require('node:test');
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { parse, compare, satisfies, compileRange } = require('./src/semver');

const versionMap = deps => ({ '1.0.0': deps });

test('numeric ordering at each component', () => {
  for (const versions of [['9.0.0', '10.0.0'], ['1.9.0', '1.10.0'], ['1.0.9', '1.0.10']]) {
    assert.deepEqual(resolve({ a: Object.fromEntries(versions.map(v => [v, {}])) }, { a: '*' }), { a: versions[1] });
  }
});

test('rollback removes partially discovered self-conflicting dependencies', () => {
  const registry = {
    a: { '2.0.0': { b: '2.0.0', a: '1.0.0' }, '1.0.0': { b: '1.0.0' } },
    b: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
});

test('rollback removes exhausted descendants and unreachable dependencies', () => {
  const registry = {
    a: { '2.0.0': { b: '2.0.0' }, '1.0.0': { b: '1.0.0' } },
    b: { '2.0.0': { missing: '*' }, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
});

test('all root constraints are collected before selection and survive rollback', () => {
  const registry = {
    a: { '2.0.0': { b: '2.0.0' }, '1.0.0': { b: '1.0.0' } },
    b: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*', b: '1.0.0' }), { a: '1.0.0', b: '1.0.0' });
});

test('first solution respects FIFO discovery rather than recursive expansion', () => {
  const registry = {
    a: { '2.0.0': { c: '*' } },
    b: { '2.0.0': { c: '1.0.0' }, '1.0.0': { c: '2.0.0' } },
    c: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), { a: '2.0.0', b: '2.0.0', c: '1.0.0' });
});

test('discovery immediately constrains selected packages and retries the latest choice', () => {
  const registry = {
    a: { '2.0.0': {}, '1.0.0': {} },
    b: { '2.0.0': { a: '1.0.0' }, '1.0.0': { a: '2.0.0' } },
  };
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), { a: '2.0.0', b: '1.0.0' });
});

test('cycles terminate and conflicting cycles are unsatisfiable', () => {
  assert.deepEqual(resolve({ a: versionMap({ a: '*' }) }, { a: '*' }), { a: '1.0.0' });
  assert.deepEqual(resolve({ a: versionMap({ b: '*' }), b: versionMap({ a: '*' }) }, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
  assert.equal(resolve({ a: versionMap({ b: '*' }), b: versionMap({ a: '2.0.0' }) }, { a: '*' }), null);
});

test('long dependency chains work without recursion or iteration limits', () => {
  const registry = {};
  const expected = {};
  for (let i = 0; i < 20000; i++) {
    registry['p' + i] = versionMap(i === 19999 ? { p0: '*' } : { ['p' + (i + 1)]: '*' });
    expected['p' + i] = '1.0.0';
  }
  assert.deepEqual(resolve(registry, { p0: '*' }), expected);
});

test('prunes conflicts before unrelated candidate combinations', () => {
  const registry = { a: { '2.0.0': { a: '1.0.0' }, '1.0.0': {} } };
  const root = { a: '*' };
  const expected = { a: '1.0.0' };
  for (let i = 0; i < 40; i++) {
    registry['p' + i] = { '2.0.0': {}, '1.0.0': {} };
    root['p' + i] = '*';
    expected['p' + i] = '2.0.0';
  }
  assert.deepEqual(resolve(registry, root), expected);
});

test('eager validation includes unreachable entries and empty roots', () => {
  const badMaps = [null, [], 0, new Date()];
  for (const bad of badMaps) {
    assert.throws(() => resolve(bad, {}), TypeError);
    assert.throws(() => resolve({}, bad), TypeError);
    assert.throws(() => resolve({ unused: bad }, {}), TypeError);
    assert.throws(() => resolve({ unused: versionMap(bad) }, {}), TypeError);
  }
  assert.throws(() => resolve({ unused: { '01.0.0': {} } }, {}), TypeError);
  assert.throws(() => resolve({ unused: versionMap({ missing: 'garbage' }) }, {}), TypeError);
  assert.deepEqual(resolve({}, {}), {});
  assert.equal(resolve({}, { missing: '*' }), null);
});

test('own enumerable keys, null prototypes, special names, and input immutability', () => {
  const registry = Object.create(null);
  const root = Object.create(null);
  const expected = {};
  for (const name of ['__proto__', 'constructor', 'toString']) {
    registry[name] = Object.freeze(versionMap(Object.freeze({})));
    root[name] = '*';
    Object.defineProperty(expected, name, { value: '1.0.0', enumerable: true });
  }
  Object.defineProperty(registry, 'hidden', { value: null });
  Object.defineProperty(root, 'hidden', { value: 'invalid' });
  Object.freeze(registry);
  Object.freeze(root);
  assert.deepEqual(resolve(registry, root), expected);
  assert.equal(Object.getPrototypeOf(resolve(registry, root)), Object.prototype);
});

test('canonical semver validation and numeric comparison', () => {
  assert.deepEqual(parse('9007199254740991.0.0'), [Number.MAX_SAFE_INTEGER, 0, 0]);
  assert.equal(compare('1.10.0', '1.9.0'), 1);
  assert.equal(compare('0.0.1', '0.1.0'), -1);
  assert.equal(compare('1.2.3', '1.2.3'), 0);
  for (const invalid of ['1.0.0\n', '1.0.0\r', '1.0.0\r\n', '1.0.0\u2028', '1.0.0\u2029', ' 1.0.0', '01.0.0', '1.0', '1.0.0-beta', '9007199254740992.0.0', null]) {
    assert.throws(() => parse(invalid), TypeError);
  }
});

