    for (const v of inside) { assert.equal(satisfies(v, range), true, `${v} in ${range}`); assert.equal(accepts(parse(v)), true); }
    for (const v of outside) { assert.equal(satisfies(v, range), false, `${v} outside ${range}`); assert.equal(accepts(parse(v)), false); }
  }
  assert.deepEqual(resolve({ a: { '0.3.0': {}, '0.2.9': {} } }, { a: '^0.2.3' }), { a: '0.2.9' });
});

test('AND terms, comparison boundaries, and invalid ranges', () => {
  for (const [range, yes, no] of [
    ['1.2.3', '1.2.3', '1.2.4'], ['>=1.2.3', '1.2.3', '1.2.2'],
    ['>1.2.3', '1.2.4', '1.2.3'], ['<=1.2.3', '1.2.3', '1.2.4'],
    ['<1.2.3', '1.2.2', '1.2.3'], [' \t>=1.0.0\n<2.0.0 * ', '1.9.0', '2.0.0'],
  ]) {
    assert.equal(satisfies(yes, range), true);
    assert.equal(satisfies(no, range), false);
  }
  for (const invalid of ['', ' ', null, 1, '^', '>= 1.0.0', '1.0.0 || 2.0.0', '1.x', 'v1.0.0', '* garbage']) {
    assert.throws(() => compileRange(invalid), TypeError);
  }
});

test('deep unsuccessful branches unwind without recursion', () => {
  const registry = {};
  for (let i = 0; i < 12000; i++) {
    registry['p' + i] = versionMap({ ['p' + (i + 1)]: '*' });
  }
  assert.equal(resolve(registry, { p0: '*' }), null);
});

test('first-found assignment matches a small independent snapshot search', () => {
  function reference(registry, root) {
    function discover(state, deps) {
      for (const [name, range] of Object.entries(deps)) {
        if (!state.constraints.has(name)) state.constraints.set(name, []);
        state.constraints.get(name).push(range);
        state.queue.push(name);
        if (state.selected.has(name) && range !== '*' && state.selected.get(name) !== range) return false;
      }
      return true;
    }
    function search(state, cursor) {
      while (cursor < state.queue.length && state.selected.has(state.queue[cursor])) cursor++;
      if (cursor === state.queue.length) return Object.fromEntries(state.selected);
      const name = state.queue[cursor];
      const candidates = Object.keys(registry[name] || {}).sort((a, b) => Number(b.split('.')[0]) - Number(a.split('.')[0]));
      for (const version of candidates) {
        if (!state.constraints.get(name).every(range => range === '*' || range === version)) continue;
        const branch = {
          selected: new Map(state.selected),
          constraints: new Map([...state.constraints].map(([name, ranges]) => [name, ranges.slice()])),
          queue: state.queue.slice(),
        };
        branch.selected.set(name, version);
        if (!discover(branch, registry[name][version])) continue;
        const result = search(branch, cursor + 1);
        if (result !== null) return result;
      }
      return null;
    }
    const state = { selected: new Map(), constraints: new Map(), queue: [] };
    discover(state, root);
    return search(state, 0);
  }
  let seed = 123456789;
  function random(n) {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed % n;
  }
  const names = ['a', 'b', 'c', 'd', 'e', 'f'];
  const ranges = ['*', '1.0.0', '2.0.0', '10.0.0'];
  for (let trial = 0; trial < 2000; trial++) {
    const registry = {};
    const root = {};
    for (const name of names) {
      registry[name] = {};
      for (const version of ['1.0.0', '10.0.0', '2.0.0']) {
        if (random(4) === 0) continue;
        const deps = {};
        for (let j = 0, count = random(4); j < count; j++) {
          deps[random(12) === 0 ? 'missing' : names[random(names.length)]] = ranges[random(ranges.length)];
        }
        registry[name][version] = deps;
      }
    }
    for (let j = 0, count = random(5); j < count; j++) root[names[random(names.length)]] = ranges[random(ranges.length)];
    assert.deepEqual(resolve(registry, root), reference(registry, root), `trial ${trial}: ${JSON.stringify({ registry, root })}`);
  }
});
